"""Next Greater Node In Linked List — monotonic stack over the values.

Time: O(n)   Space: O(n)
"""
from typing import List

if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def nextLargerNodes(self, head) -> List[int]:
        values = []
        while head:
            values.append(head.val)
            head = head.next
        out, stack = [0] * len(values), []
        for i, value in enumerate(values):
            while stack and values[stack[-1]] < value:
                out[stack.pop()] = value
            stack.append(i)
        return out
